package org.fribok.bookkeeping.dataformat;

import se.swedsoft.bookkeeping.data.SSProduct;
import se.swedsoft.bookkeeping.data.SSProductRow;

import java.math.BigDecimal;
import java.sql.*;
import java.util.*;

/** Converts products, localized descriptions, account overrides, and ordered parcel rows. */
public final class ProductRegisterStagingConverter {
 public ConversionResult convert(Connection legacy,Connection normalized)throws SQLException{Snapshot source=readLegacy(Objects.requireNonNull(legacy));SemanticFingerprint sf=fingerprint(source);try{writeNormalized(Objects.requireNonNull(normalized),source);Snapshot dest=readNormalized(normalized);SemanticFingerprint df=fingerprint(dest);List<String>d=sf.differences(df);if(!d.isEmpty()){normalized.rollback();throw new SQLException("Product-register staging fingerprint mismatch: "+String.join("; ",d));}normalized.commit();return new ConversionResult(sf,df,source.products.size(),source.descriptions.size(),source.accounts.size(),source.components.size());}catch(SQLException|RuntimeException e){normalized.rollback();throw e;}}
 public SemanticFingerprint fingerprintNormalized(Connection c)throws SQLException{return fingerprint(readNormalized(c));}
 private static Snapshot readLegacy(Connection c)throws SQLException{Snapshot s=new Snapshot();query(c,"SELECT id,companyid,number,product FROM tbl_product ORDER BY companyid,id",r->{int id=r.getInt(1),company=r.getInt(2);String key=r.getString(3);SSProduct x=(SSProduct)r.getObject(4);x.fixResultUnitAndProject();if(!Objects.equals(key,x.getNumber()))throw new SQLException("Product key/object mismatch for legacy id "+id+": table="+key+", object="+x.getNumber());s.products.add(new Product(id,company,key,x.getDescription(),x.getStoredSellingPrice(),x.getTaxCode()==null?null:x.getTaxCode().name(),x.getWarehouseLocation(),x.getOrderpoint(),x.getOrdercount(),x.getPurchasePrice(),x.getStockPrice(),x.getUnitFreight(),x.getSupplierNr(),x.getSupplierProductNr(),x.isExpired(),x.isStockProduct(),x.getUnit()==null?null:x.getUnit().getName(),x.getStoredWeight(),x.getStoredVolume(),x.getProjectNr(),x.getResultUnitNr()));x.getDescriptions().entrySet().stream().sorted(Comparator.comparing(e->e.getKey().toLanguageTag())).forEach(e->s.descriptions.add(new Description(id,e.getKey().toLanguageTag(),e.getValue())));x.getStoredDefaultAccounts().entrySet().stream().sorted(Map.Entry.comparingByKey(Comparator.comparing(Enum::name))).forEach(e->s.accounts.add(new Account(id,e.getKey().name(),e.getValue())));int row=0;for(SSProductRow p:x.getParcelRows())s.components.add(new Component(id,row++,p.getProductNr(),p.getDescription(),p.getQuantity()));});s.sort();return s;}
 private static void writeNormalized(Connection c,Snapshot s)throws SQLException{for(Product r:s.products){try(PreparedStatement p=c.prepareStatement("INSERT INTO product (legacy_id,company_id,number,description,selling_price,tax_code,warehouse_location,order_point,order_count,purchase_price,stock_price,unit_freight,supplier_number,supplier_product_number,expired,stock_goods,unit_name,weight,volume,project_number,result_unit_number) SELECT ?,id,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,? FROM company WHERE legacy_id=?",Statement.RETURN_GENERATED_KEYS)){int i=1;p.setInt(i++,r.legacyId);for(String v:Arrays.asList(r.number,r.description))p.setString(i++,v);p.setBigDecimal(i++,r.sellingPrice);p.setString(i++,r.taxCode);p.setString(i++,r.warehouse);setInteger(p,i++,r.orderPoint);setInteger(p,i++,r.orderCount);p.setBigDecimal(i++,r.purchasePrice);p.setBigDecimal(i++,r.stockPrice);p.setBigDecimal(i++,r.freight);p.setString(i++,r.supplierNumber);p.setString(i++,r.supplierProductNumber);p.setBoolean(i++,r.expired);p.setBoolean(i++,r.stockGoods);p.setString(i++,r.unit);p.setBigDecimal(i++,r.weight);p.setBigDecimal(i++,r.volume);p.setString(i++,r.project);p.setString(i++,r.resultUnit);p.setInt(i,r.companyLegacyId);if(p.executeUpdate()!=1)throw new SQLException("Missing company "+r.companyLegacyId+" for product "+r.legacyId);r.normalizedId=key(p);}}Map<Integer,Long>ids=new HashMap<>();for(Product r:s.products)ids.put(r.legacyId,r.normalizedId);for(Description r:s.descriptions)insert(c,"product_description",ids,r.productLegacyId,r.locale,List.of(r.description));for(Account r:s.accounts)insertNumber(c,ids,r);for(Component r:s.components){Long id=required(ids,r.productLegacyId);try(PreparedStatement p=c.prepareStatement("INSERT INTO product_component VALUES (?,?,?,?,?)")){p.setLong(1,id);p.setInt(2,r.row);p.setString(3,r.productNumber);p.setString(4,r.description);setInteger(p,5,r.quantity);p.executeUpdate();}}}
 private static Snapshot readNormalized(Connection c)throws SQLException{Snapshot s=new Snapshot();query(c,"SELECT p.id,p.legacy_id,c.legacy_id,p.number,p.description,p.selling_price,p.tax_code,p.warehouse_location,p.order_point,p.order_count,p.purchase_price,p.stock_price,p.unit_freight,p.supplier_number,p.supplier_product_number,p.expired,p.stock_goods,p.unit_name,p.weight,p.volume,p.project_number,p.result_unit_number FROM product p JOIN company c ON c.id=p.company_id ORDER BY c.legacy_id,p.id",r->{Product x=new Product(r.getInt(2),r.getInt(3),r.getString(4),r.getString(5),r.getBigDecimal(6),r.getString(7),r.getString(8),nullableInteger(r,9),nullableInteger(r,10),r.getBigDecimal(11),r.getBigDecimal(12),r.getBigDecimal(13),r.getString(14),r.getString(15),r.getBoolean(16),r.getBoolean(17),r.getString(18),r.getBigDecimal(19),r.getBigDecimal(20),r.getString(21),r.getString(22));x.normalizedId=r.getLong(1);s.products.add(x);});query(c,"SELECT p.legacy_id,d.locale_tag,d.description FROM product_description d JOIN product p ON p.id=d.product_id ORDER BY p.legacy_id,d.locale_tag",r->s.descriptions.add(new Description(r.getInt(1),r.getString(2),r.getString(3))));query(c,"SELECT p.legacy_id,a.account_type,a.account_number FROM product_default_account a JOIN product p ON p.id=a.product_id ORDER BY p.legacy_id,a.account_type",r->s.accounts.add(new Account(r.getInt(1),r.getString(2),nullableInteger(r,3))));query(c,"SELECT p.legacy_id,x.row_number,x.component_product_number,x.description,x.quantity FROM product_component x JOIN product p ON p.id=x.product_id ORDER BY p.legacy_id,x.row_number",r->s.components.add(new Component(r.getInt(1),r.getInt(2),r.getString(3),r.getString(4),nullableInteger(r,5))));s.sort();return s;}
 private static SemanticFingerprint fingerprint(Snapshot s){SemanticFingerprintBuilder b=new SemanticFingerprintBuilder();var p=b.domain("products");for(Product r:s.products)p.startRecord(r.companyLegacyId+"/"+r.legacyId).writeInteger(r.legacyId).writeInteger(r.companyLegacyId).writeString(r.number).writeString(r.description).writeDecimal(canon(r.sellingPrice)).writeString(r.taxCode).writeString(r.warehouse).writeInteger(r.orderPoint).writeInteger(r.orderCount).writeDecimal(canon(r.purchasePrice)).writeDecimal(canon(r.stockPrice)).writeDecimal(canon(r.freight)).writeString(r.supplierNumber).writeString(r.supplierProductNumber).writeBoolean(r.expired).writeBoolean(r.stockGoods).writeString(r.unit).writeDecimal(canon(r.weight)).writeDecimal(canon(r.volume)).writeString(r.project).writeString(r.resultUnit);p.finish();var d=b.domain("product-descriptions");for(Description r:s.descriptions)d.startRecord(r.productLegacyId+"/"+r.locale).writeInteger(r.productLegacyId).writeString(r.locale).writeString(r.description);d.finish();var a=b.domain("product-default-accounts");for(Account r:s.accounts)a.startRecord(r.productLegacyId+"/"+r.type).writeInteger(r.productLegacyId).writeString(r.type).writeInteger(r.number);a.finish();var x=b.domain("product-components");for(Component r:s.components)x.startRecord(r.productLegacyId+"/"+r.row).writeInteger(r.productLegacyId).writeInteger(r.row).writeString(r.productNumber).writeString(r.description).writeInteger(r.quantity);x.finish();return b.finish();}
 private static BigDecimal canon(BigDecimal v){return v==null?null:v.signum()==0?BigDecimal.ZERO:v.stripTrailingZeros();}private static void setInteger(PreparedStatement p,int i,Integer v)throws SQLException{if(v==null)p.setNull(i,Types.INTEGER);else p.setInt(i,v);}private static Integer nullableInteger(ResultSet r,int i)throws SQLException{int v=r.getInt(i);return r.wasNull()?null:v;}private static long key(PreparedStatement p)throws SQLException{try(ResultSet r=p.getGeneratedKeys()){if(!r.next())throw new SQLException("Missing generated product key");return r.getLong(1);}}private static Long required(Map<Integer,Long>m,int k)throws SQLException{Long v=m.get(k);if(v==null)throw new SQLException("Missing product mapping "+k);return v;}private static void query(Connection c,String sql,SqlRow f)throws SQLException{try(Statement p=c.createStatement();ResultSet r=p.executeQuery(sql)){while(r.next())f.accept(r);}}private static void insert(Connection c,String table,Map<Integer,Long>ids,int legacy,String key,List<String>values)throws SQLException{try(PreparedStatement p=c.prepareStatement("INSERT INTO "+table+" VALUES (?,?,?)")){p.setLong(1,required(ids,legacy));p.setString(2,key);p.setString(3,values.get(0));p.executeUpdate();}}private static void insertNumber(Connection c,Map<Integer,Long>ids,Account r)throws SQLException{try(PreparedStatement p=c.prepareStatement("INSERT INTO product_default_account VALUES (?,?,?)")){p.setLong(1,required(ids,r.productLegacyId));p.setString(2,r.type);setInteger(p,3,r.number);p.executeUpdate();}}
 public record ConversionResult(SemanticFingerprint sourceFingerprint,SemanticFingerprint destinationFingerprint,long products,long descriptions,long defaultAccounts,long components){}@FunctionalInterface private interface SqlRow{void accept(ResultSet r)throws SQLException;}
 private static final class Product{final int legacyId,companyLegacyId;final String number,description;final BigDecimal sellingPrice;final String taxCode,warehouse;final Integer orderPoint,orderCount;final BigDecimal purchasePrice,stockPrice,freight;final String supplierNumber,supplierProductNumber;final boolean expired,stockGoods;final String unit;final BigDecimal weight,volume;final String project,resultUnit;long normalizedId;Product(int legacyId,int companyLegacyId,String number,String description,BigDecimal sellingPrice,String taxCode,String warehouse,Integer orderPoint,Integer orderCount,BigDecimal purchasePrice,BigDecimal stockPrice,BigDecimal freight,String supplierNumber,String supplierProductNumber,boolean expired,boolean stockGoods,String unit,BigDecimal weight,BigDecimal volume,String project,String resultUnit){this.legacyId=legacyId;this.companyLegacyId=companyLegacyId;this.number=number;this.description=description;this.sellingPrice=sellingPrice;this.taxCode=taxCode;this.warehouse=warehouse;this.orderPoint=orderPoint;this.orderCount=orderCount;this.purchasePrice=purchasePrice;this.stockPrice=stockPrice;this.freight=freight;this.supplierNumber=supplierNumber;this.supplierProductNumber=supplierProductNumber;this.expired=expired;this.stockGoods=stockGoods;this.unit=unit;this.weight=weight;this.volume=volume;this.project=project;this.resultUnit=resultUnit;}}
 private record Description(int productLegacyId,String locale,String description){}private record Account(int productLegacyId,String type,Integer number){}private record Component(int productLegacyId,int row,String productNumber,String description,Integer quantity){}private static final class Snapshot{final List<Product>products=new ArrayList<>();final List<Description>descriptions=new ArrayList<>();final List<Account>accounts=new ArrayList<>();final List<Component>components=new ArrayList<>();void sort(){products.sort(Comparator.comparingInt((Product r)->r.companyLegacyId).thenComparingInt(r->r.legacyId));descriptions.sort(Comparator.comparingInt(Description::productLegacyId).thenComparing(Description::locale));accounts.sort(Comparator.comparingInt(Account::productLegacyId).thenComparing(Account::type));components.sort(Comparator.comparingInt(Component::productLegacyId).thenComparingInt(Component::row));}}
}
